# glm47_agent/config.py

from __future__ import annotations

import os
from dataclasses import dataclass
from pathlib import Path


def _env_bool(name: str, default: bool) -> bool:
    value = os.getenv(name)
    if value is None:
        return default
    normalized = value.strip().lower()
    if normalized in {"1", "true", "yes", "on"}:
        return True
    if normalized in {"0", "false", "no", "off"}:
        return False
    raise ValueError(f"Invalid boolean for {name}: {value!r}")


def _env_int(name: str, default: int) -> int:
    value = os.getenv(name)
    return default if value is None else int(value.strip())


def _env_float(name: str, default: float) -> float:
    value = os.getenv(name)
    return default if value is None else float(value.strip())


@dataclass(slots=True)
class AgentConfig:
    api_key: str
    model: str = "glm-4.7"
    base_url: str = ""
    workspace_dir: Path = Path(".").resolve()
    max_steps: int = 24
    max_completion_tokens: int = 8192
    temperature: float = 0.2
    reasoning_effort: str = "high"
    clear_thinking: bool = False
    parallel_tool_calls: bool = True
    request_timeout_seconds: int = 300
    max_retries: int = 4
    user_id: str | None = None

    @classmethod
    def from_env(cls, workspace_dir: str | None = None) -> "AgentConfig":
        api_key = os.getenv("ZAI_API_KEY") or os.getenv("OPENAI_API_KEY")
        if not api_key:
            raise ValueError("Set ZAI_API_KEY or OPENAI_API_KEY in the environment.")

        resolved_workspace = Path(
            workspace_dir or os.getenv("AGENT_WORKSPACE", ".")
        ).expanduser().resolve()
        resolved_workspace.mkdir(parents=True, exist_ok=True)

        config = cls(
            api_key=api_key,
            model=os.getenv("ZAI_MODEL", "glm-4.7"),
            base_url=os.getenv("ZAI_BASE_URL", "").rstrip("/"),
            workspace_dir=resolved_workspace,
            max_steps=_env_int("AGENT_MAX_STEPS", 24),
            max_completion_tokens=_env_int("AGENT_MAX_COMPLETION_TOKENS", 8192),
            temperature=_env_float("AGENT_TEMPERATURE", 0.2),
            reasoning_effort=os.getenv("AGENT_REASONING_EFFORT", "high").strip(),
            clear_thinking=_env_bool("AGENT_CLEAR_THINKING", False),
            parallel_tool_calls=_env_bool("AGENT_PARALLEL_TOOL_CALLS", True),
            request_timeout_seconds=_env_int("AGENT_REQUEST_TIMEOUT_SECONDS", 300),
            max_retries=_env_int("AGENT_MAX_RETRIES", 4),
            user_id=os.getenv("AGENT_USER_ID"),
        )
        config.validate()
        return config

    def validate(self) -> None:
        if not self.api_key.strip():
            raise ValueError("API key cannot be empty.")
        if self.max_steps < 1:
            raise ValueError("max_steps must be >= 1.")
        if self.max_completion_tokens < 256:
            raise ValueError("max_completion_tokens must be >= 256.")
        if not (0.0 <= self.temperature <= 2.0):
            raise ValueError("temperature must be between 0.0 and 2.0.")
        if self.reasoning_effort not in {"low", "medium", "high", "none"}:
            raise ValueError("reasoning_effort must be one of: low, medium, high, none.")
        if self.request_timeout_seconds < 5:
            raise ValueError("request_timeout_seconds must be >= 5.")
        if self.max_retries < 0:
            raise ValueError("max_retries must be >= 0.")
        self.workspace_dir.mkdir(parents=True, exist_ok=True)
```

