# glm47_agent/tools.py

from __future__ import annotations

import json
import mimetypes
import os
import subprocess
import tempfile
from dataclasses import dataclass
from pathlib import Path
from typing import Any

import requests


def _truncate(text: str, max_chars: int = 32000) -> str:
    if len(text) <= max_chars:
        return text
    return text[:max_chars] + "\n[TRUNCATED]"


def _is_text_content_type(content_type: str) -> bool:
    content_type = (content_type or "").lower()
    if content_type.startswith("text/"):
        return True
    return any(
        marker in content_type
        for marker in (
            "json",
            "xml",
            "javascript",
            "x-www-form-urlencoded",
            "yaml",
            "toml",
            "csv",
            "html",
        )
    )


@dataclass(slots=True)
class Workspace:
    root: Path

    def __post_init__(self) -> None:
        self.root = self.root.expanduser().resolve()
        self.root.mkdir(parents=True, exist_ok=True)

    def resolve(self, relative_path: str) -> Path:
        candidate = (self.root / relative_path).expanduser().resolve()
        if not candidate.is_relative_to(self.root):
            raise PermissionError(f"Path escapes workspace: {relative_path!r}")
        return candidate

    def list_dir(self, path: str = ".", recursive: bool = False, max_entries: int = 200) -> dict[str, Any]:
        target = self.resolve(path)
        if not target.exists():
            raise FileNotFoundError(f"Directory does not exist: {path}")
        if not target.is_dir():
            raise NotADirectoryError(f"Path is not a directory: {path}")

        entries: list[dict[str, Any]] = []
        iterator = target.rglob("*") if recursive else target.iterdir()

        for item in iterator:
            relative = item.relative_to(self.root).as_posix()
            kind = "dir" if item.is_dir() else "file"
            size = item.stat().st_size if item.is_file() else None
            entries.append({"path": relative, "type": kind, "size": size})
            if len(entries) >= max_entries:
                break

        entries.sort(key=lambda x: (x["type"] != "dir", x["path"]))
        return {
            "ok": True,
            "path": target.relative_to(self.root).as_posix(),
            "recursive": recursive,
            "entry_count": len(entries),
            "entries": entries,
        }

    def read_file(self, path: str, start_line: int = 1, end_line: int | None = None) -> dict[str, Any]:
        target = self.resolve(path)
        if not target.exists():
            raise FileNotFoundError(f"File does not exist: {path}")
        if not target.is_file():
            raise IsADirectoryError(f"Path is not a file: {path}")

        mime_type, _ = mimetypes.guess_type(target.name)
        raw = target.read_bytes()
        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError:
            text = raw.decode("utf-8", errors="replace")

        lines = text.splitlines()
        total_lines = len(lines)

        normalized_start = max(start_line, 1)
        normalized_end = total_lines if end_line is None else min(max(end_line, normalized_start), total_lines)

        excerpt = lines[normalized_start - 1 : normalized_end]
        numbered = "\n".join(
            f"{line_no}: {line}"
            for line_no, line in enumerate(excerpt, start=normalized_start)
        )

        return {
            "ok": True,
            "path": target.relative_to(self.root).as_posix(),
            "mime_type": mime_type or "application/octet-stream",
            "line_range": [normalized_start, normalized_end],
            "total_lines": total_lines,
            "content": _truncate(numbered, 32000),
        }

    def write_file(self, path: str, content: str, create_parents: bool = True) -> dict[str, Any]:
        target = self.resolve(path)
        if create_parents:
            target.parent.mkdir(parents=True, exist_ok=True)

        with tempfile.NamedTemporaryFile(
            mode="w",
            encoding="utf-8",
            dir=str(target.parent),
            delete=False,
            newline=""
        ) as handle:
            handle.write(content)
            temp_name = handle.name

        os.replace(temp_name, target)

        return {
            "ok": True,
            "path": target.relative_to(self.root).as_posix(),
            "bytes_written": target.stat().st_size,
        }

    def run_command(self, command: str, cwd: str = ".", timeout_sec: int = 120) -> dict[str, Any]:
        working_dir = self.resolve(cwd)
        if not working_dir.exists():
            raise FileNotFoundError(f"Working directory does not exist: {cwd}")
        if not working_dir.is_dir():
            raise NotADirectoryError(f"Working directory is not a directory: {cwd}")

        completed = subprocess.run(
            ["bash", "-lc", command],
            cwd=str(working_dir),
            capture_output=True,
            text=True,
            timeout=timeout_sec,
            env=os.environ.copy(),
        )

        return {
            "ok": completed.returncode == 0,
            "cwd": working_dir.relative_to(self.root).as_posix(),
            "command": command,
            "returncode": completed.returncode,
            "stdout": _truncate(completed.stdout, 32000),
            "stderr": _truncate(completed.stderr, 32000),
        }

    def fetch_url(self, url: str, timeout_sec: int = 30, max_chars: int = 50000) -> dict[str, Any]:
        response = requests.get(
            url,
            timeout=timeout_sec,
            headers={"User-Agent": "glm47-autonomous-agent/1.0"},
        )
        content_type = response.headers.get("content-type", "")
        body: str

        if _is_text_content_type(content_type):
            response.encoding = response.encoding or response.apparent_encoding or "utf-8"
            body = _truncate(response.text, max_chars)
        else:
            body = f"[NON_TEXT_RESPONSE: {content_type or 'unknown'}]"

        return {
            "ok": response.ok,
            "url": str(response.url),
            "status_code": response.status_code,
            "content_type": content_type,
            "headers": dict(response.headers),
            "body": body,
        }


TOOL_SPECS: list[dict[str, Any]] = [
