        "function": {
            "name": "fetch_url",
            "description": "Fetch a URL and return text content or response metadata.",
            "parameters": {
                "type": "object",
                "properties": {
                    "url": {"type": "string", "description": "HTTP or HTTPS URL to fetch."},
                    "timeout_sec": {"type": "integer", "minimum": 1, "maximum": 300},
                    "max_chars": {"type": "integer", "minimum": 100, "maximum": 200000},
                },
                "required": ["url"],
                "additionalProperties": False,
            },
        },
    },
]


def run_tool(name: str, arguments: dict[str, Any], workspace: Workspace) -> dict[str, Any]:
    try:
        if name == "list_dir":
            return workspace.list_dir(
                path=arguments.get("path", "."),
                recursive=arguments.get("recursive", False),
                max_entries=arguments.get("max_entries", 200),
            )
        if name == "read_file":
            return workspace.read_file(
                path=arguments["path"],
                start_line=arguments.get("start_line", 1),
                end_line=arguments.get("end_line"),
            )
        if name == "write_file":
            return workspace.write_file(
                path=arguments["path"],
                content=arguments["content"],
                create_parents=arguments.get("create_parents", True),
            )
        if name == "run_command":
            return workspace.run_command(
                command=arguments["command"],
                cwd=arguments.get("cwd", "."),
                timeout_sec=arguments.get("timeout_sec", 120),
            )
        if name == "fetch_url":
            return workspace.fetch_url(
                url=arguments["url"],
                timeout_sec=arguments.get("timeout_sec", 30),
                max_chars=arguments.get("max_chars", 50000),
            )
        return {"ok": False, "error": f"Unknown tool: {name}"}
    except Exception as exc:
        return {
            "ok": False,
            "error": type(exc).__name__,
            "message": str(exc),
            "tool": name,
            "arguments": arguments,
        }


def json_result(data: dict[str, Any]) -> str:
    return json.dumps(data, ensure_ascii=False, indent=2)
