# Z.AI recommends preserved thinking for coding and agent scenarios by setting `clear_thinking: false`, and it says prior reasoning content should be returned unmodified to keep reasoning coherent. [web:10]
# Z.AI documents GLM-4.7 series as having enhanced programming capability and more stable multi-step reasoning and execution. [web:13]

from __future__ import annotations

import json
import time
from typing import Any

import requests

from .config import AgentConfig


class APIError(RuntimeError):
    pass


class ZAIChatCompletionsClient:
    def __init__(self, config: AgentConfig) -> None:
        self.config = config
        self.session = requests.Session()
        self.endpoint = f"{self.config.base_url.rstrip('/')}/chat/completions"

    def close(self) -> None:
        self.session.close()

    def _headers(self) -> dict[str, str]:
        return {
            "Authorization": f"Bearer {self.config.api_key}",
            "Content-Type": "application/json",
        }

    def create_chat_completion(
        self,
        messages: list[dict[str, Any]],
        tools: list[dict[str, Any]],
    ) -> dict[str, Any]:
        payload: dict[str, Any] = {
            "model": self.config.model,
            "messages": messages,
            "tools": tools,
            "tool_choice": "auto",
            "parallel_tool_calls": self.config.parallel_tool_calls,
            "clear_thinking": self.config.clear_thinking,
            "reasoning_effort": self.config.reasoning_effort,
            "max_completion_tokens": self.config.max_completion_tokens,
            "temperature": self.config.temperature,
            "stream": False,
        }
        if self.config.user_id:
            payload["user"] = self.config.user_id

        last_error: Exception | None = None
        for attempt in range(self.config.max_retries + 1):
            try:
                response = self.session.post(
                    self.endpoint,
                    headers=self._headers(),
                    data=json.dumps(payload, ensure_ascii=False),
                    timeout=(10, self.config.request_timeout_seconds),
                )

                if response.status_code in {429, 500, 502, 503, 504} and attempt < self.config.max_retries:
                    time.sleep(min(2 ** attempt, 8))
                    continue

                response.raise_for_status()
                parsed = response.json()
                if "choices" not in parsed or not parsed["choices"]:
                    raise APIError(f"Malformed response: {parsed!r}")
                return parsed
            except (requests.RequestException, ValueError, APIError) as exc:
                last_error = exc
                if attempt >= self.config.max_retries:
                    break
                time.sleep(min(2 ** attempt, 8))

        raise APIError(f"Chat completion failed after retries: {last_error}") from last_error
