# glm47_agent/agent.py

from __future__ import annotations

import json
from typing import Any, Callable

from .client import APIError, ZAIChatCompletionsClient
from .config import AgentConfig
from .tools import TOOL_SPECS, Workspace, json_result, run_tool


SYSTEM_PROMPT = """You are an autonomous software agent running inside a workspace.
You can inspect files, edit files, run shell commands, and fetch URLs.
Operate step by step, use tools whenever they improve reliability, and verify important changes.
When editing code, prefer complete file rewrites over partial snippets.
When you are done, return the final answer directly.
"""

DEVELOPER_PROMPT = """Execution policy:
- Never assume file contents; inspect before modifying when necessary.
- Prefer deterministic commands.
- Keep tool arguments valid JSON.
- If a tool fails, reason about the failure and recover.
- Preserve code correctness, syntax, and filesystem safety.
"""


class AgentError(RuntimeError):
    pass


EventHandler = Callable[[str, dict[str, Any]], None]


class AutonomousAgent:
    def __init__(self, config: AgentConfig, on_event: EventHandler | None = None) -> None:
        self.config = config
        self.client = ZAIChatCompletionsClient(config)
        self.workspace = Workspace(config.workspace_dir)
        self.on_event = on_event
        self._messages: list[dict[str, Any]] = [
            {"role": "system", "content": SYSTEM_PROMPT},
            {"role": "developer", "content": DEVELOPER_PROMPT},
        ]

    def close(self) -> None:
        self.client.close()

    def reset(self) -> None:
        self._messages = [
            {"role": "system", "content": SYSTEM_PROMPT},
            {"role": "developer", "content": DEVELOPER_PROMPT},
        ]

    def _emit(self, event_name: str, payload: dict[str, Any]) -> None:
        if self.on_event is not None:
            self.on_event(event_name, payload)

    @staticmethod
    def _assistant_message_payload(message: dict[str, Any]) -> dict[str, Any]:
        payload: dict[str, Any] = {
            "role": "assistant",
            "content": message.get("content"),
        }

        if message.get("tool_calls") is not None:
            payload["tool_calls"] = message["tool_calls"]

        if message.get("reasoning") is not None:
            payload["reasoning"] = message["reasoning"]

        if message.get("reasoning_content") is not None:
            payload["reasoning_content"] = message["reasoning_content"]

        return payload

    @staticmethod
    def _parse_arguments(raw_arguments: str | None) -> dict[str, Any]:
        if raw_arguments is None or raw_arguments.strip() == "":
            return {}
        return json.loads(raw_arguments)

    def _execute_tool_calls(self, tool_calls: list[dict[str, Any]]) -> None:
        for tool_call in tool_calls:
            call_id = tool_call["id"]
            function = tool_call.get("function", {})
            name = function.get("name", "")
            raw_arguments = function.get("arguments", "{}")

            try:
                arguments = self._parse_arguments(raw_arguments)
            except Exception as exc:
                result = {
                    "ok": False,
                    "error": "InvalidToolArguments",
                    "message": str(exc),
                    "raw_arguments": raw_arguments,
                }
                self._messages.append(
                    {
                        "role": "tool",
                        "tool_call_id": call_id,
                        "content": json_result(result),
                    }
                )
                self._emit(
                    "tool_error",
                    {
                        "tool_name": name,
                        "tool_call_id": call_id,
                        "error": str(exc),
                    },
                )
                continue

            self._emit(
                "tool_start",
                {
                    "tool_name": name,
                    "tool_call_id": call_id,
                    "arguments": arguments,
                },
            )
            result = run_tool(name=name, arguments=arguments, workspace=self.workspace)
            self._messages.append(
                {
                    "role": "tool",
                    "tool_call_id": call_id,
                    "content": json_result(result),
                }
            )
            self._emit(
                "tool_end",
                {
                    "tool_name": name,
                    "tool_call_id": call_id,
                    "result_ok": result.get("ok", False),
                },
            )

    def run(self, task: str) -> str:
        self._messages.append({"role": "user", "content": task})

        for step in range(1, self.config.max_steps + 1):
            self._emit("model_request", {"step": step, "message_count": len(self._messages)})
            try:
                response = self.client.create_chat_completion(
                    messages=self._messages,
                    tools=TOOL_SPECS,
                )
            except APIError as exc:
                raise AgentError(str(exc)) from exc

            choice = response["choices"][0]
            message = choice["message"]
            finish_reason = choice.get("finish_reason")
            assistant_payload = self._assistant_message_payload(message)
            self._messages.append(assistant_payload)
            self._emit(
                "model_response",
                {
                    "step": step,
                    "finish_reason": finish_reason,
                    "has_tool_calls": bool(message.get("tool_calls")),
                },
            )

            if message.get("tool_calls"):
                self._execute_tool_calls(message["tool_calls"])
                continue

            content = message.get("content")
            if isinstance(content, str) and content.strip():
                return content

            raise AgentError(f"Model returned no content and no tool calls at step {step}.")

        raise AgentError(f"Max steps exceeded without a final answer: {self.config.max_steps}")
