# glm47_agent/cli.py

from __future__ import annotations

import argparse
import sys
from pathlib import Path
from typing import Any

from .agent import AgentError, AutonomousAgent
from .config import AgentConfig


def _stderr(message: str) -> None:
    sys.stderr.write(message + "\n")
    sys.stderr.flush()


def _event_logger(event_name: str, payload: dict[str, Any]) -> None:
    if event_name == "tool_start":
        _stderr(f"[tool:start] {payload['tool_name']} {payload['arguments']}")
    elif event_name == "tool_end":
        _stderr(f"[tool:end] {payload['tool_name']} ok={payload['result_ok']}")
    elif event_name == "tool_error":
        _stderr(f"[tool:error] {payload['tool_name']} {payload['error']}")
    elif event_name == "model_request":
        _stderr(f"[model:request] step={payload['step']} messages={payload['message_count']}")
    elif event_name == "model_response":
        _stderr(
            f"[model:response] step={payload['step']} finish_reason={payload['finish_reason']} "
            f"tool_calls={payload['has_tool_calls']}"
        )


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="glm47-agent",
        description="Autonomous agent powered by GLM-4.7.",
    )
    parser.add_argument(
        "task",
        nargs="?",
        help="Task for the agent. If omitted, stdin or interactive mode is used.",
    )
    parser.add_argument(
        "--workspace",
        default=".",
        help="Workspace directory for files and commands.",
    )
    parser.add_argument(
        "--model",
        default=None,
        help="Override the model name from the environment.",
    )
    parser.add_argument(
        "--base-url",
        default=None,
        help="Override the API base URL from the environment.",
    )
    parser.add_argument(
        "--max-steps",
        type=int,
        default=None,
        help="Override the maximum number of agent iterations.",
    )
    parser.add_argument(
        "--temperature",
        type=float,
        default=None,
        help="Override temperature for the request.",
    )
    parser.add_argument(
        "--reasoning-effort",
        choices=["low", "medium", "high", "none"],
        default=None,
        help="Override reasoning effort.",
    )
    parser.add_argument(
        "--clear-thinking",
        action="store_true",
        help="Enable clear_thinking=true for this session.",
    )
    parser.add_argument(
        "--verbose",
        action="store_true",
        help="Print model and tool activity to stderr.",
    )
    return parser


def _read_task_from_stdin_or_prompt(args: argparse.Namespace) -> str:
    if args.task:
        return args.task

    if not sys.stdin.isatty():
        data = sys.stdin.read().strip()
        if data:
            return data

    _stderr("Interactive mode. Type /exit to quit and /reset to clear history.")
    return ""


def main() -> int:
    parser = _build_parser()
    args = parser.parse_args()

    try:
        config = AgentConfig.from_env(workspace_dir=args.workspace)
        if args.model:
            config.model = args.model
        if args.base_url:
            config.base_url = args.base_url.rstrip("/")
        if args.max_steps is not None:
            config.max_steps = args.max_steps
        if args.temperature is not None:
            config.temperature = args.temperature
        if args.reasoning_effort is not None:
            config.reasoning_effort = args.reasoning_effort
        if args.clear_thinking:
            config.clear_thinking = True
        config.workspace_dir = Path(args.workspace).expanduser().resolve()
        config.validate()
    except Exception as exc:
        _stderr(f"Configuration error: {exc}")
        return 2

    logger = _event_logger if args.verbose else None
    agent = AutonomousAgent(config=config, on_event=logger)

    try:
        initial_task = _read_task_from_stdin_or_prompt(args)
        if initial_task:
            result = agent.run(initial_task)
            sys.stdout.write(result + "\n")
            sys.stdout.flush()
            return 0

        while True:
            try:
                task = input("glm47-agent> ").strip()
            except EOFError:
                _stderr("")
                break

            if not task:
                continue
            if task == "/exit":
                break
            if task == "/reset":
                agent.reset()
                _stderr("Conversation reset.")
                continue

            try:
                result = agent.run(task)
                sys.stdout.write(result + "\n")
                sys.stdout.flush()
            except AgentError as exc:
                _stderr(f"Agent error: {exc}")

        return 0
    finally:
        agent.close()


if __name__ == "__main__":
    raise SystemExit(main())
